#### Phase 3: Integrate with EaaS Consumer Application

**Step 1: Kafka Consumer Integration (Python Example)**

```python
# src/consumers/kafka_consumer_with_retry.py
import asyncio
from kafka import KafkaConsumer
from kafka.errors import KafkaError
import json
import logging

from retry.retry_orchestrator import RetryOrchestrator, ProcessingResult
from retry.error_classifier import ErrorClassifier

logger = logging.getLogger(__name__)

class KafkaConsumerWithRetry:
    """Kafka consumer with integrated retry pattern."""

    def __init__(
        self,
        bootstrap_servers: list,
        topic: str,
        group_id: str,
        retry_orchestrator: RetryOrchestrator
    ):
        self.consumer = KafkaConsumer(
            topic,
            bootstrap_servers=bootstrap_servers,
            group_id=group_id,
            auto_offset_reset='earliest',
            enable_auto_commit=False,  # Manual commit after successful processing/DLQ routing
            value_deserializer=lambda m: json.loads(m.decode('utf-8'))
        )
        self.retry_orchestrator = retry_orchestrator
        self.running = True

    async def process_event(self, event: dict):
        """
        Process event - implement your business logic here.
        This is the function that will be wrapped with retry logic.
        """
        # Example: Call downstream API
        # This would typically call your actual business logic
        claim_id = event['payload']['claim_id']

        # Simulate API call that may fail
        async with aiohttp.ClientSession() as session:
            async with session.post(
                'https://api.example.com/claims/validate',
                json={'claim_id': claim_id},
                timeout=aiohttp.ClientTimeout(total=5)
            ) as response:
                response.raise_for_status()  # Raises HTTPError for 4xx/5xx
                return await response.json()

    async def consume(self):
        """Main consumer loop with retry integration."""
        logger.info("Starting Kafka consumer with retry pattern")

        while self.running:
            # Poll for messages (blocking with timeout)
            messages = self.consumer.poll(timeout_ms=1000, max_records=10)

            for topic_partition, records in messages.items():
                for record in records:
                    try:
                        event = record.value
                        logger.info(f"Received event: {event.get('event_id')}")

                        # Execute with retry
                        result = await self.retry_orchestrator.execute_with_retry(
                            event=event,
                            processor=self.process_event,
                            circuit_breaker_state="CLOSED"  # Integrate with actual circuit breaker
                        )

                        # Commit offset after successful processing or DLQ routing
                        if result in [ProcessingResult.SUCCESS, ProcessingResult.DLQ_ROUTED, ProcessingResult.CIRCUIT_OPEN]:
                            self.consumer.commit()
                            logger.info(f"Committed offset for event {event.get('event_id')}, result={result}")

                    except Exception as ex:
                        logger.error(f"Unexpected error in consumer loop: {ex}", exc_info=True)
                        # Do not commit offset - message will be reprocessed on restart

            # Small delay to prevent tight loop
            await asyncio.sleep(0.1)

    def stop(self):
        """Stop the consumer gracefully."""
        self.running = False
        self.consumer.close()
