# src/consumers/rabbitmq_consumer_with_retry.py
import aio_pika
import json
import logging
from typing import Optional

from retry.retry_orchestrator import RetryOrchestrator, ProcessingResult

logger = logging.getLogger(__name__)

class RabbitMQConsumerWithRetry:
    """RabbitMQ consumer with integrated retry pattern."""

    def __init__(
        self,
        connection_url: str,
        queue_name: str,
        retry_orchestrator: RetryOrchestrator
    ):
        self.connection_url = connection_url
        self.queue_name = queue_name
        self.retry_orchestrator = retry_orchestrator
        self.connection: Optional[aio_pika.Connection] = None
        self.channel: Optional[aio_pika.Channel] = None

    async def connect(self):
        """Establish RabbitMQ connection."""
        self.connection = await aio_pika.connect_robust(self.connection_url)
        self.channel = await self.connection.channel()
        await self.channel.set_qos(prefetch_count=10)  # Process 10 messages concurrently
        logger.info(f"Connected to RabbitMQ, consuming from queue: {self.queue_name}")

    async def process_event(self, event: dict):
        """Process event - implement your business logic here."""
        member_id = event['payload']['member_id']

        # Example: Update eligibility in database
        # This would call your actual business logic
        logger.info(f"Processing eligibility update for member {member_id}")

        # Simulate processing that may fail
        # Your actual implementation here
        pass

    async def message_handler(self, message: aio_pika.IncomingMessage):
        """Handle individual message with retry pattern."""
        async with message.process(ignore_processed=True):
            try:
                event = json.loads(message.body.decode())
                logger.info(f"Received event: {event.get('event_id')}")

                # Execute with retry
                result = await self.retry_orchestrator.execute_with_retry(
                    event=event,
                    processor=self.process_event,
                    circuit_breaker_state="CLOSED"
                )

                if result == ProcessingResult.SUCCESS:
                    # Acknowledge message (successful processing)
                    await message.ack()
                    logger.info(f"Acknowledged event {event.get('event_id')}")

                elif result in [ProcessingResult.DLQ_ROUTED, ProcessingResult.CIRCUIT_OPEN]:
                    # Reject message without requeue (already in DLQ)
                    await message.reject(requeue=False)
                    logger.warning(f"Rejected event {event.get('event_id')}, routed to DLQ")

            except Exception as ex:
                logger.error(f"Unexpected error in message handler: {ex}", exc_info=True)
                # Reject with requeue for unexpected errors
                await message.reject(requeue=True)

    async def consume(self):
        """Start consuming messages."""
        await self.connect()
        queue = await self.channel.declare_queue(self.queue_name, durable=True)
        await queue.consume(self.message_handler)
        logger.info("RabbitMQ consumer started with retry pattern")

    async def close(self):
        """Close connection gracefully."""
        if self.connection and not self.connection.is_closed:
            await self.connection.close()
