package com.gainwell.eaas.consumer;

import com.gainwell.eaas.retry.*;
import org.apache.kafka.clients.consumer.*;
import org.apache.kafka.common.serialization.StringDeserializer;
import org.slf4j.Logger;
import org.slf4j.LoggerFactory;

import java.time.Duration;
import java.util.*;
import java.util.concurrent.CompletableFuture;

public class KafkaConsumerWithRetry {
    private static final Logger logger = LoggerFactory.getLogger(KafkaConsumerWithRetry.class);

    private final KafkaConsumer<String, String> consumer;
    private final RetryOrchestrator retryOrchestrator;
    private volatile boolean running = true;

    public KafkaConsumerWithRetry(
        String bootstrapServers,
        String topic,
        String groupId,
        RetryOrchestrator retryOrchestrator
    ) {
        Properties props = new Properties();
        props.put(ConsumerConfig.BOOTSTRAP_SERVERS_CONFIG, bootstrapServers);
        props.put(ConsumerConfig.GROUP_ID_CONFIG, groupId);
        props.put(ConsumerConfig.KEY_DESERIALIZER_CLASS_CONFIG, StringDeserializer.class.getName());
        props.put(ConsumerConfig.VALUE_DESERIALIZER_CLASS_CONFIG, StringDeserializer.class.getName());
        props.put(ConsumerConfig.ENABLE_AUTO_COMMIT_CONFIG, "false");

        this.consumer = new KafkaConsumer<>(props);
        this.consumer.subscribe(Collections.singletonList(topic));
        this.retryOrchestrator = retryOrchestrator;
    }

    public void consume() {
        logger.info("Starting Kafka consumer with retry pattern");

        while (running) {
            ConsumerRecords<String, String> records = consumer.poll(Duration.ofMillis(1000));

            for (ConsumerRecord<String, String> record : records) {
                try {
                    Map<String, Object> event = parseEvent(record.value());
                    logger.info("Received event: {}", event.get("event_id"));

                    // Execute with retry
                    CompletableFuture<String> resultFuture = retryOrchestrator.executeWithRetry(
                        event,
                        this::processEvent,
                        "CLOSED"  // Circuit breaker state
                    );

                    String result = resultFuture.get();  // Block until processing completes

                    // Commit offset after successful processing or DLQ routing
                    if (result.equals("SUCCESS") || result.equals("DLQ_ROUTED") || result.equals("CIRCUIT_OPEN")) {
                        consumer.commitSync();
                        logger.info("Committed offset for event {}, result={}", event.get("event_id"), result);
                    }

                } catch (Exception ex) {
                    logger.error("Unexpected error in consumer loop", ex);
                    // Do not commit - message will be reprocessed
                }
            }
        }

        consumer.close();
    }

    private CompletableFuture<Void> processEvent(Map<String, Object> event) {
