#### Phase 4: Configure Observability and Monitoring

**Step 1: Implement Metrics Emitter (Python Example)**

```python
# src/monitoring/metrics_emitter.py
import boto3
from datetime import datetime
import logging

from retry.retry_context import RetryContext
from retry.error_classifier import RetryDecision

logger = logging.getLogger(__name__)

class MetricsEmitter:
    """Emits retry metrics to CloudWatch."""

    def __init__(self, namespace: str = "EaaS/EventProcessing"):
        self.cloudwatch = boto3.client('cloudwatch')
        self.namespace = namespace

    def emit_retry_attempt(self, context: RetryContext, decision: RetryDecision):
        """Emit metrics for a retry attempt."""
        try:
            self.cloudwatch.put_metric_data(
                Namespace=self.namespace,
                MetricData=[
                    {
                        'MetricName': 'RetryAttempt',
                        'Value': 1,
                        'Unit': 'Count',
                        'Timestamp': datetime.utcnow(),
                        'Dimensions': [
                            {'Name': 'ConsumerApplication', 'Value': context.consumer_application},
                            {'Name': 'DownstreamService', 'Value': context.downstream_service},
                            {'Name': 'ErrorType', 'Value': context.error_type or 'Unknown'},
                            {'Name': 'RetryDecision', 'Value': decision.value}
                        ]
                    },
                    {
                        'MetricName': 'RetryAttemptNumber',
                        'Value': context.retry_attempt,
                        'Unit': 'Count',
                        'Timestamp': datetime.utcnow(),
                        'Dimensions': [
                            {'Name': 'ConsumerApplication', 'Value': context.consumer_application},
                            {'Name': 'DownstreamService', 'Value': context.downstream_service}
                        ]
                    }
                ]
            )
        except Exception as ex:
            logger.error(f"Failed to emit retry attempt metrics: {ex}")

    def emit_retry_success(self, context: RetryContext):
        """Emit metrics for successful processing after retries."""
        try:
            duration = (context.last_attempt_timestamp - context.first_attempt_timestamp).total_seconds()

            self.cloudwatch.put_metric_data(
                Namespace=self.namespace,
                MetricData=[
                    {
                        'MetricName': 'EventProcessingSuccess',
                        'Value': 1,
                        'Unit': 'Count',
                        'Timestamp': datetime.utcnow(),
                        'Dimensions': [
                            {'Name': 'ConsumerApplication', 'Value': context.consumer_application},
                            {'Name': 'DownstreamService', 'Value': context.downstream_service}
                        ]
                    },
                    {
                        'MetricName': 'RetrySuccessAfterAttempts',
                        'Value': context.retry_attempt,
                        'Unit': 'Count',
                        'Timestamp': datetime.utcnow(),
                        'Dimensions': [
                            {'Name': 'ConsumerApplication', 'Value': context.consumer_application}
                        ]
                    },
                    {
                        'MetricName': 'TotalProcessingDuration',
                        'Value': duration,
                        'Unit': 'Seconds',
                        'Timestamp': datetime.utcnow(),
                        'Dimensions': [
                            {'Name': 'ConsumerApplication', 'Value': context.consumer_application}
                        ]
                    }
                ]
            )
        except Exception as ex:
            logger.error(f"Failed to emit retry success metrics: {ex}")
